const menuButton=document.querySelector('.menu-toggle');
const navigation=document.querySelector('#navigation');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','메뉴 열기');navigation.classList.remove('open');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');navigation.classList.toggle('open',open);});
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){closeMenu();menuButton.focus();}});
const products={ball:{english:'BALL BEARING',title:'볼 베어링',description:'볼을 전동체로 사용해 회전을 지지하는 베어링입니다. 다양한 회전 장치에 사용되며, 구조에 따라 지지할 수 있는 하중과 회전 특성이 달라집니다.',feature:'볼 형태의 전동체 · 다양한 형식',application:'전동기, 펌프, 일반 산업기계'},roller:{english:'ROLLER BEARING',title:'롤러 베어링',description:'롤러를 전동체로 사용하는 베어링입니다. 다양한 롤러 형식이 있으며, 하중의 방향과 크기, 장비의 회전 조건에 맞추어 검토합니다.',feature:'롤러 형태의 전동체 · 하중 지지',application:'산업용 감속기, 공작기계, 중장비'},taper:{english:'TAPERED ROLLER BEARING',title:'테이퍼 롤러 베어링',description:'원뿔 형태의 롤러를 사용하는 베어링입니다. 반경 방향과 축 방향의 하중을 함께 지지하도록 설계되며, 설치 배열과 조정 조건을 함께 고려합니다.',feature:'테이퍼 롤러 · 복합 하중 지지',application:'차축, 감속기, 산업용 구동 장치'}};
const tabs=Array.from(document.querySelectorAll('[role="tab"]'));
function selectProduct(tab){const item=products[tab.dataset.product];tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1;});document.querySelector('#product-panel').setAttribute('aria-labelledby',tab.id);['english','title','description','feature','application'].forEach(key=>document.querySelector('#product-'+key).textContent=item[key]);}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectProduct(tab));tab.addEventListener('keydown',e=>{let next=index;if(e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();selectProduct(tabs[next]);tabs[next].focus();});});
const inquiry='[삼호엔지니어링 제품 문의]\n제품 품번: \n규격(내경 × 외경 × 폭): \n사용 장비: \n회전 속도 및 사용 환경: \n필요 수량: \n희망 납기: \n담당자 및 회신 연락처: ';
document.querySelector('#copy-inquiry').addEventListener('click',async()=>{const feedback=document.querySelector('#copy-feedback');try{await navigator.clipboard.writeText(inquiry);feedback.textContent='문의 양식을 복사했습니다. 내용을 채워 상담에 활용해 주세요.';}catch{const field=document.querySelector('#inquiry-fallback');field.hidden=false;field.value=inquiry;field.focus();field.select();feedback.textContent='아래 양식을 선택해 직접 복사해 주세요.';}});
document.querySelector('#year').textContent=new Date().getFullYear();
